#[test]
fn test_execution_path_determinism() {
    use kdb::record_execution;

    let input = 42u64;
    let trace1 = record_execution(|| compute(input)).unwrap();
    let trace2 = record_execution(|| compute(input)).unwrap();

    // Verify identical execution paths
    assert_eq!(trace1.instructions.len(), trace2.instructions.len());
    for (i1, i2) in trace1.instructions.iter().zip(trace2.instructions.iter()) {
        assert_eq!(i1.addr, i2.addr);
        assert_eq!(i1.opcode, i2.opcode);
    }
}

#[test]
fn test_bitwise_reproducibility() {
    let input = [1.0f32, 2.0, 3.0, 4.0];
    let baseline = compute_simd(&input);

    // 100+ runs, bitwise identical
    for _ in 0..100 {
        let output = compute_simd(&input);
        assert_eq!(&baseline[..], &output[..], "Bitwise mismatch detected!");
    }
}

#[test]
fn test_generation_monotonicity() {
    let capsules: Vec<_> = (0..100).map(|_| DualAtomicU64::new()).collect();
    let mut all_gens = Vec::new();

    for capsule in &capsules {
        for _ in 0..10_000 {
            capsule.store(1, Ordering::Release);
            all_gens.push(capsule.generation());
        }
    }

    // Verify unique
    let unique: HashSet<_> = all_gens.iter().cloned().collect();
    assert_eq!(unique.len(), all_gens.len());
}

