#[test]
fn test_memory_ordering() {
    let x = Arc::new(AtomicU64::new(0));
    let y = Arc::new(AtomicU64::new(0));

    let x1 = Arc::clone(&x);
    let t1 = thread::spawn(move || {
        x1.store(1, Ordering::Release); // Release fence
    });

    let y1 = Arc::clone(&y);
    let t2 = thread::spawn(move || {
        while y1.load(Ordering::Relaxed) == 0 {}
        // Acquire: prevents later loads from moving before
        let val = x.load(Ordering::Acquire);
        assert_eq!(val, 1); // Should always be true
    });

    y.store(1, Ordering::Relaxed);
    t1.join().unwrap();
    t2.join().unwrap();
}

#[test]
fn test_deterministic_replay() {
    let capsule = DualAtomicU64::new();

    // Record initial state
    capsule.store(42, Ordering::Release);
    let gen1 = capsule.generation();

    // Execute and snapshot
    capsule.store(100, Ordering::Release);
    let gen2 = capsule.generation();

    // Verify deterministic behavior
    assert!(gen2 > gen1);

    // kdb would:
    // 1. Record all snapshots
    // 2. Replay from snapshot
    // 3. Verify final state matches
}

#[test]
fn test_composition_determinism() {
    // Run 100+ times
    for _ in 0..100 {
        // T1: Atomic store
        let atomic = DualAtomicU64::new();
        atomic.store(100, Ordering::Release);

        // T2: SIMD computation
        let input = std::simd::i32x4::from_array([1, 2, 3, 4]);
        let simd_result = input.wrapping_mul(std::simd::i32x4::splat(2));

        // T3: Fixed-point P&L
        let fixed_val = fixed::types::I16F16::from_num(100);
        let computed = fixed_val + fixed::types::I16F16::from_num(200);

        // Verify all remain deterministic
        assert_eq!(atomic.load(Ordering::Acquire), 100);
        assert_eq!(computed, fixed::types::I16F16::from_num(300));
    }
}
